@page "/catalog"
@using sv_5bb5332bd99c47dc9ddf606512cc397b.Components.Pages.Catalog
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <CatalogFilters Categories="@_categories"
                    OnFiltersApplied="HandleFiltersApplied"
                    OnFiltersCleared="HandleFiltersCleared" />

    <main class="catalog-main">
        @if (_error is not null)
        {
            <div class="catalog-error" role="alert">
                <p>Something went wrong: @_error</p>
                <button @onclick="LoadProducts">Retry</button>
            </div>
        }
        else if (_loading)
        {
            <div class="catalog-loading" aria-live="polite">
                <p>Loading products...</p>
            </div>
        }
        else if (_products is null || _products.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@_totalCount"
                            Page="@_page"
                            PageSize="@PageSize"
                            OnSortChanged="HandleSortChanged" />

            <div class="product-grid">
                @foreach (var product in _products)
                {
                    <ProductCard Product="@product"
                                 OnSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            @if (_totalPages > 1)
            {
                <CatalogPagination CurrentPage="@_page"
                                   TotalPages="@_totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </main>
</div>

@code {
    private const int PageSize = 12;

    [Inject] private IProductService ProductService { get; set; } = default!;

    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    private List<Product>? _products;
    private List<string>? _categories;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _page = 1;
    private int _totalCount;
    private int _totalPages;
    private bool _loading;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await LoadProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;

        try
        {
            var result = await ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);
            _products = result.Items;
            _totalCount = result.TotalCount;
            _totalPages = (int)Math.Ceiling((double)result.TotalCount / PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _products = null;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _filter = filter;
        _page = 1;
        await LoadProducts();
    }

    private async Task HandleFiltersCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _page = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _page = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _page = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart integration
        return Task.CompletedTask;
    }
}

.catalog-layout {
